n0:runApexScript.n0:source:
 declare 
 -- sqlcl version      = 26.3.0.0 
 -- override_schema    = ${apex.1000.schema}
 -- override_alias     = ${apex.1000.alias}
 -- override_workspace = ${apex.1000.workspace}
 -- override_app_id    = ${apex.1000.appId}
 -- override_offset    = ${apex.1000.offset}

 l_app_id varchar2(255) := q'[1000]';  
 l_workspace varchar2(255) := q'[JOBTRACKER]'; 

 l_override_workspace varchar2(255) := q'[${apex.1000.workspace}]'; 
 l_override_schema varchar2(255) := q'[${apex.1000.schema}]'; 
 l_override_alias varchar2(255) := q'[${apex.1000.alias}]'; 
 l_override_app_id varchar2(255) := q'[${apex.1000.appId}]'; 
 l_override_offset varchar2(255) := q'[${apex.1000.offset}]'; 
 l_generate_offset boolean := false;

 function get_prop_default(p_prop_name varchar2)
 return varchar2 is
 begin  
   return '${apex.1000.' || p_prop_name || '}';
 end;  

 begin  
  apex_application_install.clear_all(); 

  -- set workspace 
     if (l_override_workspace != l_workspace and l_override_workspace != get_prop_default('workspace')) then
      apex_application_install.set_workspace(l_override_workspace);
  else 
      apex_application_install.set_workspace(l_workspace);         
  end if; 
  commit;  

  -- set app id 
  if (l_override_app_id != l_app_id and l_override_app_id != get_prop_default('appId')) then
     apex_application_install.set_application_id(l_override_app_id);
    l_generate_offset := true;
  else  
      apex_application_install.set_application_id(l_app_id);
  end if; 

 if (l_override_schema != get_prop_default('schema')) then
    apex_application_install.set_schema(l_override_schema);
  end if;

  -- set alias 
  if (l_override_alias != get_prop_default('alias')) then
    apex_application_install.set_application_alias(l_override_alias);
   l_generate_offset := true;
 end if;

  -- set offset 
 if (l_override_offset != get_prop_default('offset') and trim(l_override_offset) is not null)  then
    apex_application_install.set_offset(to_number(l_override_offset));
 elsif (l_generate_offset)  then
    apex_application_install.generate_offset();
 end if;
end;  
/
-- sqlcl_checksum  ca1231fbe4599f052417c1856c80ca11dec11f0d
